"""One-shot Excel → Markdown extractor for NT复盘 project.
Follows file-sync skill rules X1–X5."""

from __future__ import annotations
import os, re, sys, zipfile
from pathlib import Path
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

SRC_DIR = Path(r"c:\Users\016551\OneDrive\Desktop\NT复盘")
OUT_DIR = SRC_DIR / "cursor_excel"
OUT_DIR.mkdir(exist_ok=True)

XLSX_FILES = [
    "NT Blog配图需求.xlsx",
    "NT SPEC参数（北美）-已校对(1).xlsx",
    "NT多波次作战计划_新.xlsx",
    "NT开放式滤噪灵感汇总.xlsx",
    "北美NT Listing.xlsx",
    "技术发布会launch film脚本.xlsx",
    "北美NT上市WBS表.xlsx",
]


def cell_md(val) -> str:
    if val is None:
        return ""
    s = str(val).strip()
    s = s.replace("\r\n", "<br>").replace("\n", "<br>")
    s = s.replace("|", "\\|")
    return s


def expand_merged(ws):
    for merge_range in list(ws.merged_cells.ranges):
        min_row, min_col = merge_range.min_row, merge_range.min_col
        val = ws.cell(min_row, min_col).value
        ws.unmerge_cells(str(merge_range))
        for r in range(merge_range.min_row, merge_range.max_row + 1):
            for c in range(merge_range.min_col, merge_range.max_col + 1):
                ws.cell(r, c).value = val


def detect_header_row(ws, max_scan=30):
    """X3: first row with ≥2 non-empty cells AND uniqueness ≥ 0.7."""
    max_col = ws.max_column or 1
    for r in range(1, min((ws.max_row or 1) + 1, max_scan + 1)):
        vals = [ws.cell(r, c).value for c in range(1, max_col + 1)]
        non_empty = [v for v in vals if v is not None and str(v).strip()]
        if len(non_empty) < 2:
            continue
        unique_count = len(set(str(v).strip() for v in non_empty))
        if unique_count / len(non_empty) >= 0.7:
            return r
    return 1


def find_images_in_xlsx(xlsx_path: Path, sheet_name: str) -> list[bytes]:
    """X5: parse xlsx zip to find embedded images for a given sheet."""
    images = []
    try:
        with zipfile.ZipFile(xlsx_path, "r") as zf:
            sheet_idx = None
            wb_tmp = load_workbook(xlsx_path, read_only=True, data_only=True)
            for i, name in enumerate(wb_tmp.sheetnames, 1):
                if name == sheet_name:
                    sheet_idx = i
                    break
            wb_tmp.close()
            if sheet_idx is None:
                return images

            sheet_rels_path = f"xl/worksheets/_rels/sheet{sheet_idx}.xml.rels"
            if sheet_rels_path not in zf.namelist():
                return images

            rels_content = zf.read(sheet_rels_path).decode("utf-8", errors="replace")
            drawing_matches = re.findall(r'Target="(\.\./drawings/drawing\d+\.xml)"', rels_content)
            if not drawing_matches:
                return images

            for dm in drawing_matches:
                drawing_path = "xl/drawings/" + dm.replace("../drawings/", "")
                drawing_rels = drawing_path.replace(".xml", ".xml.rels")
                drawing_rels = drawing_rels.replace("xl/drawings/", "xl/drawings/_rels/")
                if drawing_rels not in zf.namelist():
                    continue
                drels = zf.read(drawing_rels).decode("utf-8", errors="replace")
                img_matches = re.findall(r'Target="(\.\./media/[^"]+)"', drels)
                for im in img_matches:
                    media_path = "xl/media/" + im.replace("../media/", "")
                    if media_path in zf.namelist():
                        images.append(zf.read(media_path))
    except Exception:
        pass
    return images


def ocr_image_bytes(img_bytes: bytes, lang="chi_sim+eng") -> str:
    try:
        from PIL import Image
        import pytesseract, io
        Image.MAX_IMAGE_PIXELS = None
        img = Image.open(io.BytesIO(img_bytes))
        if max(img.size) > 4000:
            ratio = 4000 / max(img.size)
            img = img.resize((int(img.width * ratio), int(img.height * ratio)))
        return pytesseract.image_to_string(img, lang=lang).strip()
    except Exception as e:
        return f"_OCR 失败: {e}_"


def extract_sheet(ws, wb_path: Path, sheet_name: str) -> str:
    expand_merged(ws)
    max_row = ws.max_row or 0
    max_col = ws.max_column or 0

    if max_row == 0 or max_col == 0:
        imgs = find_images_in_xlsx(wb_path, sheet_name)
        if imgs:
            return _build_image_ocr_section(imgs, sheet_name)
        return "_（此 sheet 为空）_"

    header_row = detect_header_row(ws)
    headers_raw = [ws.cell(header_row, c).value for c in range(1, max_col + 1)]
    headers = []
    for i, h in enumerate(headers_raw):
        if h is None or str(h).strip() == "":
            headers.append(f"column_{i+1}")
        else:
            headers.append(cell_md(h))

    data_rows = []
    for r in range(header_row + 1, max_row + 1):
        row_vals = [cell_md(ws.cell(r, c).value) for c in range(1, max_col + 1)]
        if any(v for v in row_vals):
            data_rows.append(row_vals)

    if not data_rows:
        imgs = find_images_in_xlsx(wb_path, sheet_name)
        if imgs:
            return _build_image_ocr_section(imgs, sheet_name)
        return "_（此 sheet 无数据行）_"

    empty_placeholder_cols = set()
    for ci, h in enumerate(headers):
        if re.match(r"^column_\d+$", h) and all(not row[ci] for row in data_rows):
            empty_placeholder_cols.add(ci)

    keep = [i for i in range(len(headers)) if i not in empty_placeholder_cols]
    headers = [headers[i] for i in keep]
    data_rows = [[row[i] for i in keep] for row in data_rows]

    pre_header = []
    for r in range(1, header_row):
        vals = [ws.cell(r, c).value for c in range(1, max_col + 1)]
        non_empty = [str(v).strip() for v in vals if v is not None and str(v).strip()]
        if non_empty:
            pre_header.append(" ".join(non_empty))

    lines = []
    if pre_header:
        for p in pre_header:
            lines.append(f"> {p}")
        lines.append("")

    lines.append("| " + " | ".join(headers) + " |")
    lines.append("| " + " | ".join(["---"] * len(headers)) + " |")
    for row in data_rows:
        padded = row + [""] * (len(headers) - len(row))
        lines.append("| " + " | ".join(padded[:len(headers)]) + " |")

    imgs = find_images_in_xlsx(wb_path, sheet_name)
    if imgs:
        lines.append("")
        lines.append(_build_image_ocr_section(imgs, sheet_name))

    return "\n".join(lines)


def _build_image_ocr_section(imgs: list[bytes], sheet_name: str) -> str:
    lines = [f"## 图片 OCR", ""]
    ocr_count = 0
    for i, img_bytes in enumerate(imgs, 1):
        lines.append(f"### 图 {i}")
        lines.append("")
        text = ocr_image_bytes(img_bytes)
        if text and len(text) > 5:
            ocr_count += 1
            lines.append(text)
        else:
            lines.append("_OCR 未识别出文字（可能是 LOGO 或纯图）_")
        lines.append("")
    header_note = f"图片数: {len(imgs)}（其中 OCR 出文字: {ocr_count}）"
    return header_note + "\n\n" + "\n".join(lines)


def process_workbook(xlsx_path: Path):
    wb = load_workbook(xlsx_path, data_only=True)
    stem = xlsx_path.stem
    out_folder = OUT_DIR / stem
    out_folder.mkdir(exist_ok=True)

    index_lines = [f"# {stem}", ""]
    for sn in wb.sheetnames:
        ws = wb[sn]
        md_content = extract_sheet(ws, xlsx_path, sn)
        safe_name = re.sub(r'[<>:"/\\|?*]', '_', sn)
        md_path = out_folder / f"{safe_name}.md"
        md_path.write_text(f"# {sn}\n\n{md_content}\n", encoding="utf-8")
        index_lines.append(f"- [{sn}]({safe_name}.md)")
        row_count = md_content.count("\n")
        print(f"  {sn}: {row_count} lines → {md_path.name}")

    (out_folder / "index.md").write_text("\n".join(index_lines) + "\n", encoding="utf-8")
    wb.close()


def main():
    for fname in XLSX_FILES:
        fpath = SRC_DIR / fname
        if not fpath.exists():
            print(f"SKIP (not found): {fname}")
            continue
        print(f"\n=== {fname} ===")
        process_workbook(fpath)

    idx_lines = ["# Excel Sync Index", ""]
    for fname in XLSX_FILES:
        stem = Path(fname).stem
        folder = OUT_DIR / stem
        if folder.exists():
            idx_lines.append(f"- [{stem}]({stem}/index.md)")
    (OUT_DIR / "index.md").write_text("\n".join(idx_lines) + "\n", encoding="utf-8")
    print("\n✓ All done. Output in:", OUT_DIR)


if __name__ == "__main__":
    main()

